"""English versions of the glossary entries in `glossary.py` (same keys).

Examples stay Vietnamese because the statute text is always Vietnamese; only the term, the
definition and the cue description are translated.
"""

GLOSSARY_EN = {
    "norm": {"term": "Norm", "definition": "A rule of conduct drawn from one sentence of the statute: who must, may or must not do what, and under which conditions. Lexora splits each norm into parts you check against the exact text."},
    "modality": {"term": "Modality", "definition": "Whether the sentence obliges, forbids, permits or grants a right. Lexora recognises it from cue words such as “phải”, “không được”, “có quyền”."},
    "obligation": {"term": "Obligation", "definition": "Something the subject is required to do. Not doing it is a breach.", "cues": "phải, có nghĩa vụ, có trách nhiệm, bắt buộc, buộc, chịu trách nhiệm"},
    "prohibition": {"term": "Prohibition", "definition": "Something the subject must not do.", "cues": "không được, cấm, nghiêm cấm, bị cấm"},
    "entitlement": {"term": "Right", "definition": "Something the subject is entitled to or may demand; the other side must respect or meet it.", "cues": "có quyền, được quyền, được"},
    "permission": {"term": "Permission", "definition": "The subject may do it but is not required to.", "cues": "có thể, được"},
    "definition": {"term": "Definition", "definition": "A sentence that explains a term used in the statute. It does not require anyone to act.", "cues": "là, được hiểu là"},
    "procedure": {"term": "Procedure", "definition": "The steps, form or documents needed to carry out something."},
    "unknown_modality": {"term": "Modality unknown", "definition": "Lexora found no modality cue word in the sentence. Select the cue word in the text to set the modality."},
    "actor": {"term": "Subject", "definition": "The person or organisation the norm addresses: who must, may or must not act."},
    "action": {"term": "Action", "definition": "What the subject does, may do or must not do. Usually the main verb of the sentence."},
    "object": {"term": "Object", "definition": "The thing, document or content the action applies to."},
    "beneficiary": {"term": "Beneficiary", "definition": "The person who benefits when the subject carries out the norm."},
    "recipient": {"term": "Recipient", "definition": "The person who receives the information, document or property the subject hands over."},
    "counterparty": {"term": "Counterparty", "definition": "The other party in the relationship the subject takes part in, such as the other signatory of a contract."},
    "outcome": {"term": "Outcome", "definition": "The legal consequence that follows when the norm applies."},
    "conditions": {"term": "Condition", "definition": "The circumstance that must exist for the norm to apply.", "cues": "khi, nếu, trường hợp, trong thời gian"},
    "exceptions": {"term": "Exception", "definition": "A case in which the norm does not apply even though the other conditions are met.", "cues": "trừ trường hợp, trừ khi, không áp dụng"},
    "quantities": {"term": "Quantity", "definition": "A number, rate, minimum or maximum attached to the norm."},
    "deadlines": {"term": "Deadline", "definition": "A period or a point in time that must be respected."},
    "scope": {"term": "Parent context", "definition": "The lead-in sentence of the article or clause the sentence belongs to. It applies to every point below it."},
    "references": {"term": "Reference", "definition": "Where the sentence mentions another article, clause or document. Lexora links a reference only when it finds the exact target and never guesses."},
    "gap": {"term": "Sentence without a norm", "definition": "A sentence of the statute that no norm was drawn from yet. Before publishing, each one needs a norm or a “not a norm” decision, so nothing is skipped."},
    "entity": {"term": "Entity", "definition": "A person, organisation or concept a norm mentions, such as “người lao động”. Two mentions count as the same entity only when a reviewer confirms it."},
    "source_unit": {"term": "Source unit", "definition": "The article, clause or point of the source document that holds the sentence the norm was drawn from."},
    "evidence": {"term": "Evidence", "definition": "A verbatim quote with its exact character position in the source text. Every part of a norm must have evidence."},
    "approved": {"term": "Approved norm", "definition": "A norm a reviewer has checked against the exact text and accepted. Only approved norms are used to answer questions. The legal validity of the document is still not verified."},
    "ai": {"term": "AI suggested", "definition": "A norm an AI model proposed for a sentence the rules could not structure. Every value it returns is checked to appear verbatim in the sentence; you still review it like any other norm."},
    "manual": {"term": "Added by hand", "definition": "A norm the reviewer added by selecting text in the statute."},
    "cue": {"term": "Needs completing", "definition": "The sentence has a modality cue but the rules could not find its subject or action. Use Edit and select the missing parts."},
    "attention": {"term": "Needs attention", "definition": "The norm shows signs that need a careful read, such as a negation, an exception or a missing subject."},
    "revision": {"term": "Revision", "definition": "Each publish creates a new revision of the knowledge base. Old revisions are kept, and chats already started keep using the revision they started with."},
    "private": {"term": "Private base", "definition": "Its content is never sent off this machine, even when AI is enabled."},
    "public": {"term": "Public base", "definition": "Its content may be sent to an AI service when you choose to use AI for a turn."},
    "audit_duplicate_heading": {"term": "Duplicate heading number", "definition": "The parser met an article, clause or point number again under the same parent. The text is kept but joined to the earlier unit, so check it against the source. Usually a typo in the source, such as two points \u201cd)\u201d in a row or two \u201cChương XI\u201d lines."},
    "audit_orphan_heading": {"term": "Heading without a parent", "definition": "A line that looks like a clause (\u201c1.\u201d) or a point (\u201ca)\u201d) but sits under no article or clause. It stays text of the unit before it instead of becoming a unit."},
    "audit_sequence_gap": {"term": "Numbering gap", "definition": "Article or clause numbers skip, for example Article 93 right after Article 91. The source may miss a heading; when the corpus keeps only chosen articles, a gap is expected."},
    "audit_heading_variant": {"term": "Misspelled article heading", "definition": "The source misspells the word \u201cĐiều\u201d. Lexora still opens that article and records it so you know the source has a typo; the text itself is not changed."},
    "audit_quoted_text": {"term": "Quoted amendment", "definition": "This article amends another document and quotes the new text in quotation marks. Articles, clauses and points inside the quote belong to the amended document, so Lexora keeps them as text of the quoting clause and opens no sub-units. Knowledge bases do not take such articles yet."},
    "audit_unclosed_quote": {"term": "Unclosed quotation mark", "definition": "A line opens a quotation that never closes before the end of the document. Lexora ignores that mark and splits as usual; check whether the source misses a mark."},
    "audit_appendix_start": {"term": "Appendix starts", "definition": "From the \u201cPhụ lục\u201d line on come the forms attached to the document. \u201cĐiều 1.\u201d lines inside a form are not articles of the document, so Lexora does not split this part and leaves it out of retrieval records; it stays readable under Appendix."},
    "q_lookup": {"term": "Lookup", "definition": "A question about one provision, answerable from one or a few adjacent units."},
    "q_synthesis": {"term": "Synthesis", "definition": "A question that needs several provisions, across articles or documents, to answer fully."},
    "q_temporal": {"term": "Effect, amendment", "definition": "A question about when rules apply or whether a document is still in force, amended or replaced. Refuse by default unless the corpus text itself states it."},
    "q_out_of_scope": {"term": "Out of scope", "definition": "A question with no basis in the frozen corpus or outside labor law; the system should refuse."},
    "expect_answer": {"term": "Answer", "definition": "The corpus holds enough verbatim basis to answer; the annotator picks the units that hold it."},
    "expect_refuse": {"term": "Refuse", "definition": "The corpus lacks the basis, the question is out of scope, or it needs an effect check the corpus cannot prove; refusing is the right answer."},
    "relevant_units": {"term": "Relevant units", "definition": "The articles, clauses or points that actually hold the basis of the answer; pick the smallest units that suffice. They are the gold for retrieval Recall@K."},
    "paraphrase_family": {"term": "Paraphrase family", "definition": "Questions with the same meaning, worded differently. A whole family always goes to the same split, dev or held-out, so results do not leak."},
    "proposal_mode": {"term": "Labelling mode", "definition": "Each annotator chooses once: label alone or see model proposals. Seeing the same proposal makes two people agree more, so the mode is reported with agreement."},
    "kappa": {"term": "Kappa (Cohen)", "definition": "Agreement between two annotators corrected for chance: 1 is full agreement, 0 is chance level. 0.6 and above is usually read as substantial, 0.8 as strong."},
    "dice": {"term": "Dice coefficient", "definition": "Overlap of two sets of relevant units: 2 x shared units / units of both. 1 means identical sets, 0 means nothing shared."},
    "full_agreement": {"term": "Full agreement", "definition": "Share of questions where both annotators match on every field: question type, expected behavior and relevant units."},
    "held_out": {"term": "Held-out set", "definition": "Questions kept apart and run once, after the configuration is frozen on dev. Never used to choose a model, prompt or parameter."},
    "adjudication": {"term": "Adjudication", "definition": "After comparing both annotators, choose or edit one final label per item. The final label is the gold used in the experiments."},
    "frozen_version": {"term": "Frozen version", "definition": "A fixed, hashed snapshot of the corpus documents. Question sets, gold sets and experiments are tied to one version, so the text never changes underneath them."},
    "leaf_unit": {"term": "Leaf unit", "definition": "The smallest unit with nothing below it: an article without clauses, a clause without points, or a point. DK2 retrieves these."},
    "effect_status": {"term": "Effect status", "definition": "The status vbpl.vn showed when the document was fetched. Lexora keeps it for reference and does not verify legal effect itself."},
    "parser_warning": {"term": "Parser warning", "definition": "A place where splitting into chapters, articles, clauses and points is uncertain. Open the document to check each warning against the source before freezing."},
    "unassigned_text": {"term": "Text outside articles", "definition": "The start of the document before the first article: state heading, number, legal bases. Kept as is but part of no unit."},
    "f1_strict": {"term": "F1, strict match", "definition": "The harmonic mean of precision and recall. Strict: two phrases must be equal after ignoring case, spacing and edge punctuation."},
    "f1_lenient": {"term": "F1, lenient match", "definition": "Like strict F1 but tolerant of boundaries: one phrase contains the other, or at least half of the syllables overlap."},
    "dk3": {"term": "DK3", "definition": "The knowledge base an LLM extracted under the schema, with every value as the model gave it, before validation."},
    "dk4": {"term": "DK4", "definition": "DK3 after the automatic validator drops violating claims (bad schema, wrong unit, non-verbatim phrases, made-up or contradicting cues, duplicates)."},
    "modality_unverified": {"term": "Modality unverified", "definition": "The model gave a modality but the sentence has no cue word to check it against, common in list points. The claim is kept."},
    "planted_errors": {"term": "Planted errors", "definition": "Clean DK4 claims are corrupted on purpose, one error type at a time, to see how many the validator catches. Technical errors should be caught; semantic ones such as a dropped negation are not, a limit to report."},
    "rejected_claims": {"term": "Rejected", "definition": "DK3 claims that did not make it into DK4, and their share; the reasons are in the details."},
    "context": {"term": "Context", "definition": "The lead-in of the article or clause that holds the quote. Read it with the quote to understand where it applies."},
}
